export const handler = async (input) => ({
  travelContentPrompt: '判断发票内容是否属于差旅费允许报销业务场景。',
  travelContentText: String(input?.goodsName ?? '')
});

export const handler = async (input) => {
  const text = String(input?.travelContentText ?? '').replace(/[\s\u3000\-_/·,.，。()（）]/g, '').toLowerCase();
  if (!text) return { travelContentState: 'missing', travelContentClassification: 'missing' };
  const forbidden = ['保险', '餐饮', '餐费', '签证', '快递'];
  const allowed = ['机票', '航空', '飞机', '铁路', '火车', '高铁', '动车', '船票', '轮船', '大巴', '客车', '通行', '租赁', '乘车', '出租', '滴滴', '住宿', '房费', '酒店', '宾馆', '运输服务', '行李', '托运', '诊疗', '疫苗', '电信服务', '电话卡', '上网卡', '退票', '退改', '改期'];
  if (forbidden.some((keyword) => text.includes(keyword))) return { travelContentState: 'warning', travelContentClassification: 'forbidden' };
  if (allowed.some((keyword) => text.includes(keyword))) return { travelContentState: 'pass', travelContentClassification: 'allowed' };
  return { travelContentState: 'warning', travelContentClassification: 'unknown' };
};
